[CmdletBinding()]
param(
 [Parameter(Mandatory)][string]$BackupDirectory,
 [Parameter(Mandatory)][string]$PublicStatePath,
 [string]$Image='public.ecr.aws/supabase/postgres@sha256:6058a6759ab9268cff8ee70641d61f1bd75953316281b76427cf5a6b4db2eafc',
 [string]$DatabaseUrl='postgresql://postgres.koqlnjctqeaykhbqkyuj@aws-0-ap-northeast-2.pooler.supabase.com:5432/postgres?sslmode=require',
 [string]$PostgresRoot="$env:LOCALAPPDATA\AgentDeskAI\tools\postgresql-17.11-5\extracted\pgsql",
 [string]$AgeRoot="$PSScriptRoot\..\..\.tools\age\v1.3.2\age",
 [string]$SslRootCert="$env:LOCALAPPDATA\AgentDeskAI\certificates\supabase-prod-ca-2021-official.crt"
)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';. "$PSScriptRoot\Backup.Common.ps1"
$staging='koqlnjctqeaykhbqkyuj';$production='cdynahtkwtcinjzmxjcs';$expectedImage='public.ecr.aws/supabase/postgres@sha256:6058a6759ab9268cff8ee70641d61f1bd75953316281b76427cf5a6b4db2eafc'
if($Image-ne$expectedImage-or$DatabaseUrl-match[regex]::Escape($production)){throw 'Pinned image or staging project guard failed.'}
$uri=[Uri]$DatabaseUrl;if($uri.UserInfo-ne"postgres.$staging"-or$uri.Host-notlike'*.pooler.supabase.com'-or$uri.AbsolutePath-ne'/postgres'-or$uri.Query-notmatch'sslmode=require'){throw 'Exact staging session-pooler URL is required.'}
$backup=[IO.Path]::GetFullPath($BackupDirectory);$manifestPath=Join-Path $backup 'manifest.json';$archive=Join-Path $backup 'staging-database.dump.age'
foreach($p in @($manifestPath,$archive,$PublicStatePath,$SslRootCert,(Join-Path $backup 'BACKUP_COMPLETE'))){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "Required artifact missing: $p"}}
$manifest=Get-Content $manifestPath -Raw|ConvertFrom-Json;$expected=@($manifest.artifacts|Where-Object name -eq 'staging-database.dump.age')[0]
if($manifest.project_ref-ne$staging-or-not$manifest.recovery_a_verified-or-not$manifest.recovery_b_verified-or-not$manifest.archive_list_verified-or-not$manifest.privileges_included-or$manifest.plaintext_archives_written-or(Get-FileSha256Lower $archive)-ne[string]$expected.ciphertext_sha256){throw 'Verified backup manifest or ciphertext integrity failed.'}
$state=Get-Content $PublicStatePath -Raw|ConvertFrom-Json;$identityA=$state.identity_a
if((Get-FileHash $identityA.artifact -Algorithm SHA256).Hash-ne[string]$identityA.sha256){throw 'Recovery Identity A baseline mismatch.'}
$age=Join-Path $AgeRoot 'age.exe';$batchpass=Join-Path $AgeRoot 'age-plugin-batchpass.exe';$psql=Join-Path $PostgresRoot 'bin\psql.exe';foreach($p in @($age,$batchpass,$psql)){Assert-ExternalCommand $p}
$setup=(Resolve-Path "$PSScriptRoot\supabase-restore-container.sh").Path;$container='agentdesk-staging-restore-'+[Guid]::NewGuid().ToString('N')
function Unlock-A { $s=(Read-StarredSecureString 'Recovery Identity A passphrase').SecureString;if($s.Length-eq 0){$s.Dispose();throw 'Identity A passphrase is empty.'};$b=[IntPtr]::Zero;$p=$null;try{$b=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);$plain=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($b);$i=New-ProcessInfo $age @('--decrypt','-j','batchpass',[string]$identityA.artifact);$i.RedirectStandardOutput=$true;$i.RedirectStandardError=$true;$i.Environment['AGE_PASSPHRASE']=$plain;$i.Environment['PATH']=([IO.Path]::GetDirectoryName($batchpass)+';'+$i.Environment['PATH']);$p=[Diagnostics.Process]::new();$p.StartInfo=$i;if(-not$p.Start()){throw 'Identity A unlock process failed to start.'};$text=$p.StandardOutput.ReadToEnd();$null=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode-ne 0-or$text-notmatch'AGE-SECRET-KEY-1'){throw 'Identity A unlock failed.'};return $text}finally{if($p){$p.Dispose()};if($b-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b)};$plain=$null;$s.Dispose()}}
function Invoke-Source([Security.SecureString]$Password,[string]$Sql){$b=[IntPtr]::Zero;$p=$null;try{$b=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($Password);$plain=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($b);$i=[Diagnostics.ProcessStartInfo]::new();$i.FileName=$psql;$i.UseShellExecute=$false;$i.RedirectStandardOutput=$true;$i.RedirectStandardError=$true;foreach($a in @('--host',$uri.Host,'--port','5432','--username',"postgres.$staging",'--dbname','postgres','--no-password','--no-psqlrc','--quiet','--tuples-only','--no-align','--field-separator','|','--set','ON_ERROR_STOP=1','--command',$Sql)){[void]$i.ArgumentList.Add($a)};$i.Environment['PGPASSWORD']=$plain;$i.Environment['PGSSLMODE']='verify-full';$i.Environment['PGSSLROOTCERT']=$SslRootCert;$i.Environment['PGCONNECT_TIMEOUT']='10';$i.Environment['PGOPTIONS']='-c default_transaction_read_only=on -c statement_timeout=30000';$p=[Diagnostics.Process]::new();$p.StartInfo=$i;if(-not$p.Start()){throw 'Source inventory process failed to start.'};$o=$p.StandardOutput.ReadToEnd();$e=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode-ne 0){throw "Source inventory failed: $($e.Trim())"};return $o}finally{if($p){$p.Dispose()};if($b-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b)};$plain=$null}}
$inventorySql=@"
begin read only;set local statement_timeout='30s';
select 'OBJECTS',json_build_object('schemas',(select count(*) from pg_namespace where nspname in ('auth','public','storage')),'tables',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','public','storage') and c.relkind in ('r','p')),'indexes',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','public','storage') and c.relkind='i'),'functions',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('auth','public','storage')),'policies',(select count(*) from pg_policies where schemaname in ('auth','public','storage')),'grants',(select count(*) from information_schema.role_table_grants where table_schema in ('auth','public','storage')));
select 'EXT',e.extname,e.extversion,n.nspname from pg_extension e join pg_namespace n on n.oid=e.extnamespace order by e.extname;
select 'TABLE',t.table_schema,t.table_name,(xpath('/row/c/text()',query_to_xml(format('select count(*) c from %I.%I',t.table_schema,t.table_name),false,true,'')))[1]::text::bigint from information_schema.tables t where t.table_type='BASE TABLE' and t.table_schema in ('auth','public','storage') order by 2,3;
select 'GRANT',table_schema,table_name,grantee,privilege_type,is_grantable from information_schema.role_table_grants where table_schema in ('auth','public','storage') order by 2,3,4,5,6;
select 'LEDGER',coalesce(to_regclass('supabase_migrations.schema_migrations')::text,'missing');rollback;
"@
$started=$false
try{
 $id=(docker image inspect $Image --format '{{index .RepoDigests 0}}').Trim();if($LASTEXITCODE-ne 0-or$id-notmatch'6058a6759ab9'){throw 'Pinned Supabase image digest is unavailable.'}
 docker run -d --name $container --network none --read-only --tmpfs '/tmp:rw,nosuid,size=256m' --tmpfs '/var/lib/postgresql/data:rw,nosuid,size=1g' --mount "type=bind,source=$setup,target=/runner.sh,readonly" --entrypoint /bin/bash $Image /runner.sh|Out-Null;if($LASTEXITCODE-ne 0){throw 'Disposable Supabase container failed to start.'};$started=$true
 $ready=$false;foreach($n in 1..60){$logs=docker logs $container 2>&1;if($logs-match'AGENTDESK_SUPABASE_RESTORE_READY'){$ready=$true;break};Start-Sleep -Milliseconds 250};if(-not$ready){throw "Disposable Supabase database did not become ready: $logs"}
 $inspect=@(docker inspect $container|ConvertFrom-Json)[0];$mounts=@($inspect.Mounts);$portProperties=@($inspect.HostConfig.PortBindings.PSObject.Properties)
 if($inspect.HostConfig.NetworkMode-ne'none'-or$mounts.Count-ne 1-or$mounts[0].Type-ne'bind'-or$mounts[0].RW-or$portProperties.Count-ne 0){throw 'Disposable container isolation validation failed.'}
 Write-Host 'Retrieve Recovery Identity A passphrase. Stars will appear.';$identity=Unlock-A;try{$hash=Invoke-CheckedNativePipeline $age @('--decrypt','--identity','-',$archive) 'docker' @('exec','-i','--user','postgres',$container,'pg_restore','-h','/tmp','-U','postgres','-d','agentdesk_restore','--no-owner','--exit-on-error') -ProducerStandardInput $identity}finally{$identity=$null};if($hash-ne[string]$expected.plaintext_sha256){throw 'Restored stream hash mismatch.'}
 $remotePassword=(Read-StarredSecureString 'Enter the existing STAGING database password').SecureString;if($remotePassword.Length-eq 0){throw 'Staging password is empty.'};try{$source=Invoke-Source $remotePassword $inventorySql}finally{$remotePassword.Dispose()}
 $restored=(docker exec --user postgres $container psql -h /tmp -U postgres -d agentdesk_restore --no-psqlrc --quiet --tuples-only --no-align --field-separator '|' --set ON_ERROR_STOP=1 --command $inventorySql|Out-String);if($LASTEXITCODE-ne 0){throw 'Restored inventory query failed.'}
 $sourceLines=@($source-split'\r?\n'|%{$_.Trim()}|?{$_});$restoreLines=@($restored-split'\r?\n'|%{$_.Trim()}|?{$_});$differences=@(Compare-Object $sourceLines $restoreLines);$match=($differences.Count-eq 0)
 $evidence=[ordered]@{result=$(if($match){'PASS'}else{'FAIL'});project_ref=$staging;image=$Image;network='none';persistent_volumes=0;plaintext_dump_written=$false;stream_sha256=$hash;source_inventory=$sourceLines;restored_inventory=$restoreLines;inventory_differences=@($differences|%{[ordered]@{line=$_.InputObject;side=$_.SideIndicator}});inventory_match=$match;vault_plaintext_decryption_tested=$false;completed_utc=[DateTime]::UtcNow.ToString('o')};$evidence|ConvertTo-Json -Depth 7|Set-Content (Join-Path $backup 'supabase-restore-evidence.json') -Encoding utf8;if(-not$match){throw 'Source and restored canonical inventories did not match.'};$manifest.isolated_restore_verified=$true;$manifest|ConvertTo-Json -Depth 7|Set-Content $manifestPath -Encoding utf8;Write-Host "SUPABASE-COMPATIBLE ISOLATED RESTORE VERIFIED: $backup"
}finally{if($started){docker rm -f $container|Out-Null}}
